using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.IO;using UnityEngine;
public static class BalanceLiveCheck {
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Set(ForgeMvp g,string n,object v)=>typeof(ForgeMvp).GetField(n,flags).SetValue(g,v);
 static object Get(ForgeMvp g,string n)=>typeof(ForgeMvp).GetField(n,flags).GetValue(g);
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 public static async Task<string> Run(){var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();Set(g,"progressLoaded",false);Set(g,"activeSaveSlot",0);typeof(ForgeMvp).GetMethod("StopMouseTrace",flags).Invoke(g,null);typeof(ForgeMvp).GetMethod("ResetProgressForDebug",flags).Invoke(g,new object[]{false});Set(g,"showTitle",false);Application.runInBackground=true;await Task.Delay(350);Check(g.HierarchyGold==100,"fresh gold");g.HierarchyBuy(ForgeTechnology.Find(ForgeTechnology.AutomationRoot),1);Check(!g.HierarchyTechnology.Owns(ForgeTechnology.AutomationRoot)&&g.HierarchyGold==100,"first research must require crafting");
 // Isolated late-game fixture validates the live coroutine/UI; these granted funds are NOT used for pacing estimates.
 Set(g,"gold",10000000);foreach(var o in ForgeTechnology.Offers.Where(o=>o.Kind!=ForgePurchaseKind.Material).OrderBy(o=>o.Tier)){g.HierarchyBuy(o,1);Check(g.HierarchyTechnology.Owns(o),"live purchase "+o.Id);}foreach(var o in ForgeTechnology.Offers.Where(o=>o.Kind==ForgePurchaseKind.Material))g.HierarchyBuy(o,20);
 var smith=(ForgeBlacksmiths)Get(g,"blacksmiths");var cycle=UnityEngine.Object.FindAnyObjectByType<ForgeDayCycle>();cycle.Clock.Restore(1,8);smith.Normalize(8);smith.burningDay=1;smith.burningUntil=0;smith.randomState=1;smith.smiths[0].favor=0;smith.smiths[0].decayAt=8;
 g.HierarchyGame.Refresh();var view=g.HierarchyGame.codes.Values.First();view.editor.text=ForgeCampaignChecks.Final.Replace("!p","777(778(),p)\n!p");int before=g.HierarchyGold,diamonds=g.HierarchyDiamonds;var watch=System.Diagnostics.Stopwatch.StartNew();view.run.onClick.Invoke();for(int n=0;n<200&&g.HierarchyBusy;n++)await Task.Delay(100);watch.Stop();Check(!g.HierarchyBusy,"live craft timeout");Check((bool)Get(g,"campaignComplete"),"live ending condition");Check(g.HierarchyDiamonds-diamonds==3,"live quality diamond award");Check(g.HierarchyGold-before==1179,"live auto-sale receipt");await Task.Delay(200);g.HierarchyGame.Refresh();Check(g.HierarchyGame.Node("Ending").gameObject.activeInHierarchy,"ending UI visible");string text="PASS fresh game 100G / root purchase rejected; all live research purchases; actual code execution and material commitment; 1179G automatic sale; 3 diamonds; ending UI. Final craft wall-clock="+watch.Elapsed.TotalSeconds.ToString("F2")+" seconds at speed 5. Late-game funds were test fixtures, not a measured fresh-to-ending run.";Directory.CreateDirectory("Docs/QA/Balance/final");File.WriteAllText("Docs/QA/Balance/final/live-check.txt",text);return text;}
 public static string Tree(){var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();Set(g,"endingSeen",true);Set(g,"showTechTree",true);Set(g,"showProgress",false);Set(g,"showTutorial",false);typeof(ForgeMvp).GetMethod("SyncHierarchyTree",flags).Invoke(g,null);return "tree open";}
}
